def stop(self) -> None:
    async def _shutdown() -> None:
        await self.runner.cleanup()

    try:
        fut = asyncio.run_coroutine_threadsafe(_shutdown(), self.loop)
        fut.result(timeout=10)
    except Exception:
        pass
    self.loop.call_soon_threadsafe(self.loop.stop)
    self.thread.join(timeout=5)
